using System;using System.IO;using System.Reflection;using System.Xml.Linq;using System.IO.Compression;using System.Collections.Generic;using System.Security.Cryptography;using V15Update;
public static class FreshUpdaterBaseTests {
 static int checks;static void Check(bool value,string why){if(!value)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
 static string Root(){string root=Path.Combine(Path.GetTempPath(),"beo-fresh-updater-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);File.Copy(Assembly.GetExecutingAssembly().Location,Path.Combine(root,"V15VoiceStudio.exe"));return root;}
 static void Kokoro(string root){foreach(string f in new[]{"engine/sherpa-onnx-offline-tts.exe","model/model.onnx","model/voices.bin","model/tokens.txt","model/lexicon-us-en.txt","source/media/ffmpeg.exe"}){string p=Path.Combine(root,f);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,"base fixture");}Directory.CreateDirectory(Path.Combine(root,"model/espeak-ng-data"));}
 static string Package(){
  string path=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N")+".zip");
  var payloads=new Dictionary<string,byte[]>{{"V15VoiceStudio.exe",File.ReadAllBytes(Assembly.GetExecutingAssembly().Location)},{"V15Updater.exe",File.ReadAllBytes(Assembly.GetExecutingAssembly().Location)},{"source/fresh-update-marker.txt",System.Text.Encoding.UTF8.GetBytes("installed")}};
  var xml=new XElement("update",new XAttribute("product","V15VoiceStudio"),new XAttribute("version","4.1.2"),new XAttribute("kind","core"),new XAttribute("space",134217728));
  using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){
   foreach(var row in payloads){string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(row.Value)).Replace("-","").ToLowerInvariant();xml.Add(new XElement("file",new XAttribute("path",row.Key),new XAttribute("size",row.Value.Length),new XAttribute("sha256",hash)));using(var w=z.CreateEntry("payload/"+row.Key).Open())w.Write(row.Value,0,row.Value.Length);}
   using(var w=new StreamWriter(z.CreateEntry("manifest.xml").Open()))w.Write(xml);
  }return path;
 }
 static void Refused(string root,string package,string why){try{UpdateEngine.Apply(package,root,s=>{});throw new Exception("Accepted incomplete speech base: "+why);}catch(Exception e){if(e.Message.StartsWith("Accepted incomplete"))throw;Check(!File.Exists(Path.Combine(root,"source/fresh-update-marker.txt")),why);}}
 public static int Main(){try{string package=Package();string empty=Root();Refused(empty,package,"Empty app folder cannot masquerade as installed TTS");string good=Root();Kokoro(good);UpdateEngine.Apply(package,good,s=>{});Check(File.ReadAllText(Path.Combine(good,"source/fresh-update-marker.txt"))=="installed","Complete Kokoro-only app accepts a core update without Python");Check(File.Exists(Path.Combine(good,"model/model.onnx")),"Core update keeps the installed speech model");string missing=Root();Kokoro(missing);File.Delete(Path.Combine(missing,"model/voices.bin"));Refused(missing,package,"Incomplete Kokoro model is refused");string legacy=Root();Directory.CreateDirectory(Path.Combine(legacy,"ai/runtime"));Directory.CreateDirectory(Path.Combine(legacy,"ai/models"));File.WriteAllText(Path.Combine(legacy,"ai/runtime/python.exe"),"legacy fixture");UpdateEngine.Apply(package,legacy,s=>{});Check(File.Exists(Path.Combine(legacy,"source/fresh-update-marker.txt")),"Existing full Python speech bases remain compatible");Console.WriteLine("TOTAL FRESH UPDATER "+checks+" PASS");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
